          "title": "What are your greatest strengths?",
          "topicId": 1,
          "topicName": "Personal Strengths",
          "level": "Basic (Fresher)",
          "answer": "• Analytical Problem Solving: 'I have a structured approach to debugging—isolating variables and finding root causes rather than applying temporary patches.'\n• Fast Technical Adaptability: 'I quickly pick up new documentation, frameworks, and APIs to become productive in short order.'\n• Collaborative Accountability: 'I communicate transparently, document my code thoroughly, and take full ownership of my deliverables from commit to deployment.'",
