          "id": 4,
          "title": "Which of your strengths would be most useful in a Software Engineer role?",
          "topicId": 1,
          "topicName": "Personal Strengths",
          "level": "Intermediate (SDE-1)",
          "answer": "'Root-cause analytical thinking and high coachability. In enterprise systems, treating symptoms creates technical debt. My drive to understand why systems behave the way they do ensures I write maintainable, performant code. Furthermore, being coachable means I absorb feedback from senior code reviews rapidly to elevate team standards.'",
          "keyConcepts": "Root-cause depth, reducing technical debt, receptive to code reviews",
