          "title": "Can a person's greatest strength sometimes become a weakness? Explain with an example.",
          "topicId": 1,
          "topicName": "Personal Strengths",
          "level": "Advanced (SDE-2)",
          "answer": "'Yes. For example, high attention to detail is a great strength when writing security-critical code or unit tests. However, taken to an extreme, it can turn into perfectionism—spending excessive time polishing an internal module before validating business velocity. I've learned that balance is key: ship a functional MVP early, gather user feedback, and iterate.'",
