          "topicName": "Personal Strengths",
          "level": "Follow-Up",
          "answer": "'During a 36-hour hackathon, our database corrupted halfway through due to an improper migration. Rather than giving up, I stayed up throughout the night, rebuilt the schema from scratch, seeded mock endpoints, and reconnected the API layers. We presented a fully functioning demo the next morning and secured a podium finish.'",
