          "topicName": "Personal Strengths",
          "level": "Follow-Up",
          "answer": "'Yes, they would describe me as dependable, patient, and collaborative. Whenever our project group faced tight submission deadlines or difficult bugs, I was the one who kept the team organized, assisted teammates with debugging, and ensured all components integrated smoothly.'",
