          "title": "What is your biggest weakness?",
          "topicId": 2,
          "topicName": "Personal Weaknesses",
          "level": "Basic (Fresher)",
          "answer": "'Early in my engineering journey, my biggest weakness was hesitating to ask for assistance when stuck on difficult bugs because I wanted to prove I could solve everything independently. I realized this wasted valuable time. I now follow the '30-minute rule': if I am blocked after 30 minutes of systematic debugging and documentation research, I formulate a concise question and consult a senior or peer.'",
