          "topicName": "Why Software Engineering?",
          "level": "Intermediate (SDE-1)",
          "answer": "'My analytical patience and curiosity align perfectly with debugging and system architecture. I genuinely enjoy the detective work of tracing stack traces, isolating intermittent race conditions, and designing clean APIs that make collaboration seamless across teams.'",
