          "topicId": 5,
          "topicName": "Why Software Engineering?",
          "level": "Advanced (SDE-2)",
          "answer": "'Because my actions outside class prove it. Someone looking only for a job stops when the syllabus ends. I have spent countless weekends building personal projects, exploring open-source code, studying database internals, and practicing problem solving purely out of curiosity and love for the craft.'",
