          "topicId": 5,
          "topicName": "Why Software Engineering?",
          "level": "Advanced (SDE-2)",
          "answer": "'I find deep satisfaction in the craft itself. Debugging isn't a chore to me; it's an opportunity to discover system quirks and write stronger test suites. And when work is repetitive, I treat it as an engineering challenge to automate it with scripts, continuously optimizing our development workflow.'",
          "keyConcepts": "Debugging as discovery, automation mindset for repetitive tasks, joy in craftsmanship",
