          "title": "Do you think a high salary is the only measure of career success?",
          "topicId": 6,
          "topicName": "Career Success",
          "level": "Basic (Fresher)",
          "answer": "'No. A high salary is an important practical outcome, but it is a byproduct of competence, not the sole metric. True career success includes autonomy, solving intellectually challenging problems, continuous learning, and having pride in the quality of what you build.'",
