          "topicName": "Continuous Learning",
          "level": "Basic (Fresher)",
          "answer": "'I use official language documentation, engineering blogs from companies like Netflix, Uber, and Meta, technical books like 'Clean Code' and 'Designing Data-Intensive Applications', and developer platforms like GitHub and Stack Overflow.'",
