          "title": "Who is a Department Head?",
          "topicId": 3,
          "topicName": "Department Heads",
          "level": "Basic (Fresher)",
          "answer": "'A Department Head (or Vice President / Director of a function) is an executive leader responsible for the overall operational efficiency, staffing, budget, and performance of a specific organizational division—such as Engineering, Product, HR, or Quality Assurance.'",
