          "level": "Intermediate (SDE-1)",
          "answer": "• Department Head: 'Operates at the macro-level, overseeing multiple projects, hundreds of staff, departmental budgets, and executive hiring.'\n• Team Lead: 'Operates at the micro-level, guiding a specific pod of 5-10 engineers on daily tasks, code reviews, sprint commitments, and feature implementations.'",
