          "title": "How should a Department Head handle a situation where the department is unable to meet its targets?",
          "topicId": 3,
          "topicName": "Department Heads",
          "level": "Advanced (SDE-2)",
          "answer": "'They should conduct an immediate systemic diagnosis rather than assigning personal blame: evaluating whether the root cause is unrealistic deadlines, technical debt, resource shortages, or shifting client requirements. They would then re-prioritize deliverables, allocate reinforcements, and reset stakeholder expectations transparently.'",
