          "topicId": 8,
          "topicName": "Operations Department",
          "level": "Basic (Fresher)",
          "answer": "'The Operations department ensures that business processes, physical/virtual infrastructure, resource staffing, and day-to-day administrative systems function smoothly, reliably, and efficiently across the entire company.'",
