          "title": "Why is the Operations department important for the smooth functioning of an IT company?",
          "topicId": 8,
          "topicName": "Operations Department",
          "level": "Basic (Fresher)",
          "answer": "'Because engineers cannot write code without working laptops, secure VPNs, reliable power, server access, and streamlined logistics. Operations provides the foundational operational backbone that allows technical teams to focus purely on building software.'",
