          "answer": "• Customer Service: 'Handles general non-technical inquiries (account management, billing, password resets, onboarding).'\n• Technical Support (L2/L3): 'Diagnoses software bugs, inspects error logs, replicates technical anomalies, and works directly with engineering teams to deploy bug fixes.'",
