          "level": "Intermediate (SDE-1)",
          "answer": "'By following the L.A.S.T principle: Listen actively, Apologize with empathy, Solve the issue systematically, and Thank the customer. They de-escalate tension, log a high-priority ticket, and provide regular status updates until resolved.'",
