          "answer": "'Acknowledge the severity immediately, assign an urgent Sev-1 ticket, and escalate directly to the L3 engineering on-call pod. Provide the customer with an immediate temporary workaround, share ticket tracking details, and send updates every 2 hours until fully resolved.'",
