          "level": "Basic (Fresher)",
          "answer": "'The R&D department explores emerging scientific and technological paradigms (such as GenAI, quantum computing, or decentralized architectures), builds experimental prototypes, and develops proprietary intellectual property to ensure long-term company competitiveness.'",
