          "title": "Is accepting a higher salary always a valid reason to change your career decision? Explain.",
          "topicId": 11,
          "topicName": "What If You Receive a Better Job Offer?",
          "level": "Follow-Up",
          "answer": "No. Salary is only one dimension. Culture, mentorship, work-life balance, project modernness, and ethical leadership matter equally. Sacrificing a supportive culture for money often leads to early burnout and regret.",
